import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Dt6pBwm7.js";const u=JSON.parse('{"title":"TanStack Table v9 PoC: Session Retrospective","description":"","frontmatter":{},"headers":[],"relativePath":"guides/tanstack-table-v9-poc-session-retrospective.md","filePath":"guides/tanstack-table-v9-poc-session-retrospective.md"}'),i={name:"guides/tanstack-table-v9-poc-session-retrospective.md"};function d(s,e,r,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="tanstack-table-v9-poc-session-retrospective" tabindex="-1">TanStack Table v9 PoC: Session Retrospective <a class="header-anchor" href="#tanstack-table-v9-poc-session-retrospective" aria-label="Permalink to &quot;TanStack Table v9 PoC: Session Retrospective&quot;">​</a></h1><p>This document records what was tried while adding TanStack Table v9 beside v8 in this React/Vite module-based application, including mistakes, observed failures, fixes, and limits of the evidence. It is a practical supplement to the <a href="./tanstack-table-v9-legacy-react-vite">staged adoption playbook</a>, not a claim that every other monorepo will behave the same way.</p><h2 id="what-was-built" tabindex="-1">What Was Built <a class="header-anchor" href="#what-was-built" aria-label="Permalink to &quot;What Was Built&quot;">​</a></h2><ul><li>Two nested design-system workspaces: <code>@starterkit/table-v8</code> using TanStack Table 8.21.3 and <code>@starterkit/table</code> using 9.3.1, which was reported as npm <code>latest</code> at implementation time.</li><li>Two separate Baseplate modules, loaded by the real app module loader and rendered on the same application page.</li><li>Independent mock-data controls, sorting, render-to-commit samples, and a draggable table divider with 25–75% bounds.</li><li>Baseline, v8-only, and dual-version production bundle/runtime measurement stages, plus a Vite development-mode regression check.</li><li>A staged adoption playbook and a system prompt for a local Gemma model.</li></ul><p>The versions above are historical observations, not recommendations for a new adoption. Verify the registry, official docs, peer requirements, and local lockfile at the time of use.</p><h2 id="attempts-failures-and-corrections" tabindex="-1">Attempts, Failures, and Corrections <a class="header-anchor" href="#attempts-failures-and-corrections" aria-label="Permalink to &quot;Attempts, Failures, and Corrections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attempt or assumption</th><th>What actually happened</th><th>Correction</th><th>Lesson</th></tr></thead><tbody><tr><td>Use a standalone HTML file as the PoC</td><td>It did not exercise the real application module loader, workspace package resolution, layout, or host interactions. The user correctly rejected it as useless for the integration question.</td><td>Replaced it with two actual app modules importing the nested design-system packages, rendered on the main app page.</td><td>Integration PoCs must cross the same ownership and runtime boundaries as production. A standalone demo can be supplemental, not the primary evidence.</td></tr><tr><td>Load Vite&#39;s build API through Node&#39;s default package resolution</td><td>Node selected a CommonJS Vite entry where the script expected the ESM API.</td><td>Resolve Vite from the app&#39;s installed dependency, then import Vite&#39;s ESM Node entry.</td><td>In a workspace, resolve build tools from the owning app rather than assuming root resolution or module format.</td></tr><tr><td>Run the Vite build API without matching the app&#39;s working directory</td><td>Existing esbuild include paths in the Vite config are relative to <code>app</code>; running from repository root caused inconsistent inclusion behavior.</td><td>Change the measurement process working directory to <code>app</code> before invoking the build API.</td><td>Measurement automation must reproduce the real app&#39;s root and config context.</td></tr><tr><td>Assume a production build is enough to prove two same-name package imports coexist</td><td>Rollup built the two workspace dependencies, but Vite development later failed with <code>@tanstack/react-table</code> missing <code>getCoreRowModel</code> for v8.</td><td>Exclude <code>@tanstack/react-table</code> and <code>@tanstack/table-core</code> from Vite dependency prebundling so each workspace resolves its own engine. Test dev and production separately.</td><td>Vite&#39;s dev optimizer and production bundler are distinct resolution paths. Check the actual resolved module URLs and exports in both modes.</td></tr><tr><td>Exclude all table-related dependencies from optimization without checking v9&#39;s adapter graph</td><td>After separating the table engines, v9 development failed because <code>@tanstack/react-store</code>&#39;s CommonJS <code>use-sync-external-store</code> shim did not provide <code>useSyncExternalStoreWithSelector</code> as an ESM named export.</td><td>Keep the table engines excluded, but include <code>@tanstack/react-store</code> in <code>optimizeDeps.include</code> so Vite converts the adapter/shim.</td><td>Fix the narrow adapter boundary that caused the error; broad optimizer changes can create a different failure. Re-check after dependency upgrades.</td></tr><tr><td>Import v8 API names and assume they apply to v9</td><td>Direct TypeScript validation rejected the v9 generic because its row type must satisfy v9&#39;s <code>RowData</code> constraint.</td><td>Constrain the v9 component and exported column type with the installed v9 <code>RowData</code> type.</td><td>Similar-looking major APIs do not imply compatible generics or feature contracts. Use the installed declarations and matching docs.</td></tr><tr><td>Treat an editor diagnostic as stale without a compiler check</td><td>The new module&#39;s <code>@starterkit/module-editable-module</code> import did not resolve in a focused <code>tsc</code> invocation. The package declared a nonexistent <code>types</code> file.</td><td>Correct the package <code>types</code> path to its existing <code>src/module.index.tsx</code> entry.</td><td>A Vite-resolvable package can still be broken for TypeScript consumers. Validate package metadata and actual target files.</td></tr><tr><td>Typecheck the module in isolation without app-wide JSX element declarations</td><td>Once module resolution was corrected, TypeScript reported <code>lc-fa-icon</code> missing from <code>JSX.IntrinsicElements</code> in the inherited editable-module header.</td><td>Include the design system&#39;s existing <code>packages/design-system/src/types.ts</code> declaration in the focused check.</td><td>Focused TypeScript commands still need the minimal ambient declarations used by the real application. Do not patch production code to silence a test command missing its context.</td></tr><tr><td>Invoke <code>tsc</code> indirectly through <code>yarn exec</code> with flags</td><td>The command did not preserve the intended flags and emitted JavaScript beside the new TypeScript files. Vite then tried to parse JSX in <code>demo.js</code> and failed with “The JSX syntax extension is not currently enabled.”</td><td>Remove only the generated files created by that command and run the pinned root compiler directly (or use the checked-in <code>tables:typecheck</code> script).</td><td>Confirm the exact compiler invocation and emitted files. Avoid cleanup commands that might delete user source.</td></tr><tr><td>Stop propagation across the wrong boundary</td><td>Clicking sort/data controls bubbled into the host layout editor&#39;s selection handler, which tried to call <code>getSavedConfigOptions</code> on an undefined module.</td><td>Trace the selection path and contain clicks on the demo table surface. The regression check now asserts there are no page exceptions while exercising controls.</td><td>In module-based hosts, embedded widgets inherit host event semantics. Fix the owning interaction boundary, not the table engine. Avoid global propagation suppression unless the host contract requires it.</td></tr><tr><td>Install Playwright&#39;s browser using the default Node CA configuration</td><td>Browser download failed repeatedly with <code>UNABLE_TO_GET_ISSUER_CERT</code>.</td><td>Retry with <code>NODE_OPTIONS=--use-system-ca yarn playwright install chromium</code>.</td><td>When the machine has a system-trusted proxy/certificate, use the system CA store; do not disable certificate verification.</td></tr><tr><td>Treat a task-launcher failure as an app failure</td><td>The VS Code task launcher returned “Task not found” for the generated task label.</td><td>Start the existing Vite app through the terminal instead.</td><td>A missing editor task is not evidence about app correctness. Use the repo&#39;s existing command directly.</td></tr><tr><td>Validate table features only by seeing headers/data</td><td>This missed regressions in independent module state, sorting, refreshing, large row updates, responsive sizing, and the new divider.</td><td>Add browser automation against production preview and Vite dev for both modules, checking row counts, sorting, refresh, state isolation, errors, mobile layout, divider bounds, complementary widths, and keyboard commands.</td><td>Test the user&#39;s actual integration workflows, not merely component presence.</td></tr><tr><td>Read a raw table render timer as engine performance</td><td>The callback measures from component render start to layout-effect commit. It includes React scheduling and DOM work, and does not measure final paint or isolate TanStack.</td><td>Name the measurement as render-to-commit; document timer scope and record navigation/paint/module-import data separately.</td><td>A number without a precise boundary invites false conclusions. Benchmark the engine separately only if that is the decision being made.</td></tr><tr><td>Sum per-entry static dependency closures as if they were independent costs</td><td>Shared chunks/dependencies appear in more than one closure, so summing would double-count. Bundle totals also include app modules, demo controls, styles, chunking changes, and not just TanStack.</td><td>Report whole emitted-asset totals and stage deltas; show closures/module attribution separately and disclose exclusions.</td><td>Bundle deltas are useful comparative evidence only when stages are otherwise identical and accounting boundaries are explicit.</td></tr><tr><td>Call observed app-ready time a pure startup metric</td><td>The browser script samples after the expected module/table elements exist; it includes browser automation observation overhead and is environment-dependent.</td><td>Store repeated samples and medians, distinguish app readiness from table commit time, and do not compare different modes/machines as if controlled.</td><td>Keep results reproducible and label proxy measurements honestly.</td></tr></tbody></table><h2 id="measurement-snapshot-and-limits" tabindex="-1">Measurement Snapshot and Limits <a class="header-anchor" href="#measurement-snapshot-and-limits" aria-label="Permalink to &quot;Measurement Snapshot and Limits&quot;">​</a></h2><p>The checked-in reports represent one machine/browser/toolchain run from the PoC, not a general performance guarantee. The measured bundle delta between v8-only and both-version stages included the v9 module and its integration surface, demo controls, styles, and bundler chunking effects; it was not an engine-only measurement. Runtime values vary across runs and development timings are not comparable to production timings.</p><p>For a new decision, regenerate the reports with the same machine, browser, production mode, data, and stage configuration. Prefer repeated median samples. Use the reference results to validate that the scripts work, not as an acceptance threshold for a larger application.</p><h2 id="practical-checklist-for-reuse" tabindex="-1">Practical Checklist for Reuse <a class="header-anchor" href="#practical-checklist-for-reuse" aria-label="Permalink to &quot;Practical Checklist for Reuse&quot;">​</a></h2><ul><li>[ ] Begin with the real app and preserve its working v8 baseline.</li><li>[ ] Pin each major in its own workspace and verify the dependency tree.</li><li>[ ] Inspect Vite dev resolution independently of production build output.</li><li>[ ] Check package entry points and TypeScript ambient declarations.</li><li>[ ] Add real app modules before drawing integration conclusions.</li><li>[ ] Exercise both modules concurrently and test host event behavior.</li><li>[ ] Define what each bundle and runtime metric includes.</li><li>[ ] Keep results reproducible, rollback easy, and v8 consumers unmigrated until explicitly approved.</li></ul>',12)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
